const entrada = $input.first().json;
const texto = String(entrada.cenarios_gherkin || '').replace(/\r\n/g, '\n').trim();
if (!texto) throw new Error('Nenhum cenário Gherkin foi informado.');
let ambientes = [];
try { ambientes = JSON.parse(String(entrada.ambientes_json || '[]')); } catch {}
if (!Array.isArray(ambientes) || !ambientes.length) {
  ambientes = [{ nome: entrada.ambiente, tipo: entrada.ambiente_tipo, url: entrada.sistema_url, usuario: entrada.login_usuario, senha: entrada.login_senha, sem_autenticacao: entrada.ambiente_sem_autenticacao }];
}

let blocos = texto.split(/(?=^\s*(?:Cenário|Scenario):)/gmi).filter((bloco) => /^\s*(?:Cenário|Scenario):/i.test(bloco));
if (blocos.length === 0) blocos = [texto];
const executionId = String(entrada.execution_id || `n8n-${$execution.id}`);
const slug = (valor) => String(valor).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50) || 'cenario';
const normalizar = (valor) => String(valor).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const termosTipo = {
  PORTAL: ['portal', 'cliente', 'usuario final'],
  SITE: ['site', 'pagina publica', 'visitante'],
  RETAGUARDA: ['retaguarda', 'backoffice', 'administracao', 'administrador'],
  API: ['api', 'endpoint', 'servico']
};

return blocos.map((bloco, indice) => {
  const tituloEncontrado = bloco.match(/^\s*(?:Cenário|Scenario):\s*([^\n]+)/i);
  const titulo = tituloEncontrado ? tituloEncontrado[1].trim() : `Cenário ${indice + 1}`;
  const scenarioId = `CT-${String(indice + 1).padStart(3, '0')}-${slug(titulo)}`;
  const textoClassificacao = normalizar(`${titulo} ${bloco}`);
  const correspondentes = ambientes.filter(env => {
    const nome = normalizar(env.nome);
    if (nome && textoClassificacao.includes(nome)) return true;
    return (termosTipo[String(env.tipo || '').toUpperCase()] || []).some(termo => textoClassificacao.includes(termo));
  });
  const usados = correspondentes.length ? correspondentes : (ambientes.length === 1 ? ambientes : []);
  const principal = usados[0] || ambientes[0];
  const ambienteAmbiguo = ambientes.length > 1 && usados.length === 0;
  const explicitamentePublico = Boolean(principal.sem_autenticacao) || /sem autenticacao|nao autenticad|usuario anonimo|acesso publico/.test(textoClassificacao);
  const testaAutenticacao = /login|senha|autentic|credencial|sessao|persistencia de acesso|acesso direto/.test(textoClassificacao);
  const authMode = explicitamentePublico ? 'PUBLIC' : (testaAutenticacao ? 'LOGIN_TEST' : 'AUTH_REQUIRED');
  const { cenarios_gherkin, login_usuario, login_senha, ...base } = entrada;
  return { json: {
    ...base,
    execution_id: executionId,
    scenario_index: indice + 1,
    scenario_id: scenarioId,
    scenario_title: titulo,
    cenario: bloco.trim(),
    ambiente: principal.nome,
    ambiente_tipo: principal.tipo,
    ambiente_sem_autenticacao: Boolean(principal.sem_autenticacao),
    sistema_url: principal.url,
    login_usuario: String(principal.usuario || ''),
    login_senha: String(principal.senha || ''),
    ambientes_execucao_json: JSON.stringify(ambientes),
    ambientes_identificados_json: JSON.stringify(usados.map(env => ({ nome: env.nome, tipo: env.tipo, url: env.url }))),
    ambiente_ambiguo: ambienteAmbiguo,
    auth_mode: ambienteAmbiguo ? 'AMBIENTE_AMBIGUO' : authMode,
    evidence_prefix: `${executionId}-${scenarioId}`
  } };
});

const item = { ...$json };
if (!item.error) return { json: item };
const bruto = typeof item.error === 'string' ? item.error : String(item.error.message || JSON.stringify(item.error));
const texto = bruto.toLowerCase();
let codigo = 'ERRO_FERRAMENTA';
let mensagem = 'O agente encontrou uma falha de automação.';
if (texto.includes('too many requests') || texto.includes('rate limit') || texto.includes('429') || texto.includes('resource_exhausted')) {
  codigo = 'LIMITE_IA';
  mensagem = 'A cota temporária da IA foi atingida.';
} else if (texto.includes('service unavailable') || texto.includes('503')) {
  codigo = 'SERVICO_IA_INDISPONIVEL';
  mensagem = 'O serviço de IA ficou temporariamente indisponível.';
} else if (texto.includes('browser_fill_form') || texto.includes('browser_type')) {
  codigo = 'PREENCHIMENTO_FALHOU';
  mensagem = 'A ferramenta não conseguiu preencher o formulário de login.';
} else if (texto.includes('timeout') || texto.includes('timed out')) {
  codigo = 'ERRO_FERRAMENTA';
  mensagem = 'A ferramenta excedeu o tempo de resposta.';
}
item.error = { message: `${codigo}: ${mensagem}` };
return { json: item };

const origemCompleta = $("Loop Sobre Cenários").item.json;
const { login_senha, login_usuario, ambientes_json, ambientes_execucao_json, ...origem } = origemCompleta;
const erro = $json.error;
const saida = $json.output;
const bruto = typeof saida === 'string' ? saida : JSON.stringify(saida ?? '');
let resultado;
const maxIteracoes = /max iterations|stopped due to max iterations/i.test(bruto);

if (maxIteracoes) {
  resultado = {
    status: 'ERRO_AUTOMACAO',
    diagnostico_codigo: 'MAX_ITERACOES',
    resumo: 'O agente atingiu o limite de navegacao antes de concluir o cenario.',
    passos: [], evidencias: [], mapa_interface: [], falhas_reais: [],
    falhas_automacao: ['Limite de iteracoes do agente atingido']
  };
} else if (erro) {
  resultado = {
    status: 'ERRO_AUTOMACAO',
    resumo: 'O agente não conseguiu executar o cenário.',
    passos: [],
    evidencias: [],
    falhas_reais: [],
    falhas_automacao: [typeof erro === 'string' ? erro : (erro.message || JSON.stringify(erro))]
  };
} else if (saida && typeof saida === 'object') {
  resultado = saida;
} else {
  try {
    const inicioJson = bruto.indexOf('{');
    const fimJson = bruto.lastIndexOf('}');
    const candidatoJson = inicioJson >= 0 && fimJson > inicioJson
      ? bruto.slice(inicioJson, fimJson + 1)
      : bruto.trim();
    resultado = JSON.parse(candidatoJson);
  } catch {
    resultado = {
      status: 'ERRO_AUTOMACAO',
      resumo: 'A resposta do agente não estava no formato JSON esperado.',
      passos: [],
      evidencias: [],
      falhas_reais: [],
      falhas_automacao: ['Resposta inválida do agente'],
      resposta_original: bruto
    };
  }
}

const permitidos = ['PASSOU', 'FALHOU', 'BLOQUEADO', 'ERRO_AUTOMACAO'];
if (!permitidos.includes(resultado.status)) resultado.status = 'ERRO_AUTOMACAO';
if (!Array.isArray(resultado.tentativas) || resultado.tentativas.length === 0) {
  resultado.tentativas = [{
    numero: 1,
    status: resultado.status,
    resumo: resultado.resumo || '',
    evidencias: Array.isArray(resultado.evidencias) ? resultado.evidencias : []
  }];
}
resultado.tentativas = resultado.tentativas.slice(0, 2).map((tentativa, indice) => ({
  numero: indice + 1,
  status: permitidos.includes(tentativa?.status) ? tentativa.status : 'ERRO_AUTOMACAO',
  resumo: tentativa?.resumo || '',
  duration_ms: Number(tentativa?.duration_ms || 0),
  evidencias: Array.isArray(tentativa?.evidencias) ? tentativa.evidencias : []
}));

return {
  json: {
    ...origem,
    status: resultado.status,
    resultado_teste: resultado,
    data_execucao: new Date().toISOString()
  }
};

const resultados = $input.all().map((item) => item.json);
const totais = { PASSOU: 0, FALHOU: 0, BLOQUEADO: 0, ERRO_AUTOMACAO: 0 };
for (const item of resultados) totais[item.status] = (totais[item.status] || 0) + 1;
const primeiro = resultados[0] || {};
return [{
  json: {
    execution_id: primeiro.execution_id || null,
    solicitado_por: primeiro.solicitado_por || null,
    projeto: primeiro.projeto || null,
    cliente: primeiro.cliente || null,
    sprint: primeiro.sprint || null,
    sistema_url: primeiro.sistema_url || null,
    inicio_processamento: resultados[0]?.data_execucao || null,
    fim_processamento: new Date().toISOString(),
    total_cenarios: resultados.length,
    totais,
    status_geral: totais.FALHOU > 0 ? 'FALHOU' : (totais.BLOQUEADO > 0 ? 'BLOQUEADO' : (totais.ERRO_AUTOMACAO > 0 ? 'ERRO_AUTOMACAO' : 'PASSOU')),
    resultados
  }
}];

