const entrada = $json;
const headers = entrada.headers || {};
const authorization = String(headers.authorization || headers.Authorization || "");
const recebido = authorization.replace(/^Bearer\s+/i, "").trim();
const esperado = String($env.QA_AGENT_API_TOKEN || "");
if (!esperado || recebido !== esperado) throw new Error("Solicitação não autorizada.");

const body = entrada.body && typeof entrada.body === "object" ? entrada.body : {};
for (const campo of ["execution_id", "projeto", "sprint", "cenarios_gherkin"]) {
  if (!String(body[campo] || "").trim()) throw new Error(`Campo obrigatório ausente: ${campo}`);
}

const recebidos = Array.isArray(body.ambientes) && body.ambientes.length
  ? body.ambientes
  : [{
      id: null,
      nome: body.ambiente || "Manual",
      tipo: body.ambiente_tipo || "OUTRO",
      url: body.sistema_url,
      usuario: body.login_usuario,
      senha: body.login_senha,
      sem_autenticacao: body.ambiente_sem_autenticacao
    }];
const ambientes = recebidos.slice(0, 5).map((item, indice) => {
  const url = String(item?.url || "").trim();
  if (!/^https?:\/\//i.test(url)) throw new Error(`URL inválida no ambiente ${indice + 1}.`);
  const usuario = String(item?.usuario || "");
  const senha = String(item?.senha || "");
  return {
    id: item?.id ?? null,
    nome: String(item?.nome || `Ambiente ${indice + 1}`),
    tipo: String(item?.tipo || "OUTRO"),
    url,
    usuario,
    senha,
    sem_autenticacao: Boolean(item?.sem_autenticacao) || !usuario || !senha
  };
});
if (!ambientes.length) throw new Error("Nenhum ambiente foi informado.");
const principal = ambientes[0];

return { json: {
  execution_id: String(body.execution_id),
  projeto: String(body.projeto),
  cliente: String(body.cliente || ""),
  sprint: String(body.sprint),
  ambiente: principal.nome,
  ambiente_tipo: principal.tipo,
  ambiente_sem_autenticacao: principal.sem_autenticacao,
  ambientes_json: JSON.stringify(ambientes),
  sistema_url: principal.url,
  login_usuario: principal.usuario,
  login_senha: principal.senha,
  cenarios_gherkin: String(body.cenarios_gherkin),
  contexto_codigo_fonte: String(body.contexto_codigo_fonte || "").slice(0, 14000),
  solicitado_por: body.solicitado_por || null
} };

const origem = $("Loop Sobre Cenários").item.json;
return {
  json: {
    ...origem,
    agent_memory: $json.agent_memory || {
      context: "Nenhum aprendizado persistente disponível.",
      entries: []
    }
  }
};

const item = { ...$json };
const url = JSON.stringify(String(item.sistema_url));
const usuario = JSON.stringify(String(item.login_usuario));
const senha = JSON.stringify(String(item.login_senha));
item.login_script = `async (page) => {
  const firstVisible = async (candidates) => {
    for (const candidate of candidates) {
      try {
        const locator = candidate.first();
        if (await locator.count() && await locator.isVisible()) return locator;
      } catch {}
    }
    return null;
  };
  await page.goto(${url}, { waitUntil: 'domcontentloaded', timeout: 60000 });
  const userField = await firstVisible([
    page.getByLabel(/usu[aá]rio|login|e-?mail/i),
    page.getByPlaceholder(/usu[aá]rio|login|e-?mail/i),
    page.locator('input[type=email]'),
    page.locator('input[name*=user i], input[name*=login i], input[name*=email i]'),
    page.locator('input[type=text]')
  ]);
  const passwordField = await firstVisible([
    page.getByLabel(/senha|password/i),
    page.getByPlaceholder(/senha|password/i),
    page.locator('input[type=password]')
  ]);
  if (!userField || !passwordField) throw new Error('CAMPO_NAO_ENCONTRADO: login ou senha não localizado');
  await userField.fill(${usuario});
  await passwordField.fill(${senha});
  const submit = await firstVisible([
    page.getByRole('button', { name: /entrar|acessar|login|sign in|continuar/i }),
    page.locator('button[type=submit], input[type=submit]')
  ]);
  if (!submit) throw new Error('CAMPO_NAO_ENCONTRADO: botão de entrada não localizado');
  await submit.click();
  await page.waitForLoadState('domcontentloaded', { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(1000);
  if (await passwordField.isVisible().catch(() => false)) {
    const body = (await page.locator('body').innerText().catch(() => '')).slice(0, 500);
    throw new Error('CREDENCIAL_RECUSADA: formulário de login permaneceu visível. ' + body);
  }
  return { authenticated: true, url: page.url(), title: await page.title() };
}`;
return { json: item };

const origem = $("Preparar Login Determinístico").item.json;
const falhou = Boolean($json.error);
return {
  json: {
    ...origem,
    original_auth_mode: origem.auth_mode,
    auth_mode: falhou ? origem.auth_mode : 'PUBLIC',
    login_preexecutado: !falhou,
    login_diagnostico: falhou ? String($json.error?.message || $json.error) : 'Login determinístico confirmado',
    login_usuario: falhou ? origem.login_usuario : '',
    login_senha: falhou ? origem.login_senha : '',
    login_script: undefined
  }
};

const origem = $("Preparar Checkpoint de Controle").item.json;
const action = String($json.action || "RUN").toUpperCase();
return { json: { ...origem, execution_control: ["RUN", "PAUSE", "CANCEL"].includes(action) ? action : "RUN" } };
